package com.rekluzlabs.makokolorize.ui.screensimport android.net.Uriimport androidx.activity.compose.rememberLauncherForActivityResultimport androidx.activity.result.PickVisualMediaRequestimport androidx.activity.result.contract.ActivityResultContractsimport androidx.compose.foundation.BorderStrokeimport androidx.compose.foundation.Imageimport androidx.compose.foundation.clickableimport androidx.compose.foundation.layout.Arrangementimport androidx.compose.foundation.layout.Boximport androidx.compose.foundation.layout.Columnimport androidx.compose.foundation.layout.Spacerimport androidx.compose.foundation.layout.fillMaxSizeimport androidx.compose.foundation.layout.fillMaxWidthimport androidx.compose.foundation.layout.heightimport androidx.compose.foundation.layout.paddingimport androidx.compose.foundation.layout.sizeimport androidx.compose.foundation.shape.RoundedCornerShapeimport androidx.compose.material.icons.Iconsimport androidx.compose.material.icons.filled.Settingsimport androidx.compose.material.icons.outlined.CameraAltimport androidx.compose.material3.Iconimport androidx.compose.material3.IconButtonimport androidx.compose.material3.LinearProgressIndicatorimport androidx.compose.material3.MaterialThemeimport androidx.compose.material3.Textimport androidx.compose.runtime.Composableimport androidx.compose.runtime.LaunchedEffectimport androidx.compose.runtime.getValueimport androidx.compose.runtime.mutableStateOfimport androidx.compose.runtime.rememberimport androidx.compose.runtime.rememberCoroutineScopeimport androidx.compose.runtime.setValueimport androidx.compose.ui.Alignmentimport androidx.compose.ui.Modifierimport androidx.compose.ui.draw.clipimport androidx.compose.ui.res.painterResourceimport androidx.compose.ui.text.font.FontWeightimport androidx.compose.ui.text.style.TextAlignimport androidx.compose.ui.unit.dpimport androidx.compose.ui.unit.spimport com.rekluzlabs.makokolorize.Rimport androidx.compose.material3.Cardimport androidx.compose.material3.CardDefaultsimport com.rekluzlabs.makokolorize.data.model.ModelRepositoryimport kotlinx.coroutines.launchsealed class HomeState {    data object Checking : HomeState()    data object AwaitingDownload : HomeState()    data object Ready : HomeState()    data class Downloading(val progress: Float) : HomeState()    data class Error(val message: String) : HomeState()}@Composablefun HomeScreen(    onImageSelected: (Uri) -> Unit,    onNavigateToSettings: () -> Unit,    context: android.content.Context) {    val repo = remember { ModelRepository(context) }    val scope = rememberCoroutineScope()    var state by remember { mutableStateOf<HomeState>(HomeState.Checking) }    var showHome by remember { mutableStateOf(false) }    val picker = rememberLauncherForActivityResult(        contract = ActivityResultContracts.PickVisualMedia()    ) { uri: Uri? ->        uri?.let { onImageSelected(it) }    }    LaunchedEffect(Unit) {        if (repo.isModelDownloaded() && repo.isScunetModelDownloaded()) {            showHome = true        } else {            state = HomeState.AwaitingDownload        }    }    val startDownload = {        state = HomeState.Downloading(0f)        scope.launch {            downloadAllModels(repo) { p -> state = HomeState.Downloading(p) }                .onSuccess { showHome = true }                .onFailure { e ->                    state = HomeState.Error(e.message ?: "Download failed")                }        }    }    androidx.compose.animation.Crossfade(        targetState = showHome,        label = "home_transition"    ) { isHomeVisible ->        if (isHomeVisible) {            HomeContent(                onPickPhoto = { picker.launch(PickVisualMediaRequest(ActivityResultContracts.PickVisualMedia.ImageOnly)) },                onNavigateToSettings = onNavigateToSettings            )        } else {            Box(                modifier = Modifier.fillMaxSize(),                contentAlignment = Alignment.Center            ) {                when (val currentState = state) {                    is HomeState.Checking -> {}                    is HomeState.AwaitingDownload -> {                        Column(                            horizontalAlignment = Alignment.CenterHorizontally,                            verticalArrangement = Arrangement.Center,                            modifier = Modifier.padding(32.dp)                        ) {                            Image(                                painter = painterResource(id = R.mipmap.ic_launcher_foreground),                                contentDescription = "App Logo",                                modifier = Modifier                                    .size(150.dp)                                    .clip(RoundedCornerShape(32.dp))                            )                            Spacer(modifier = Modifier.height(32.dp))                            Text(                                text = "Welcome to Makokolorize",                                fontSize = 22.sp,                                fontWeight = FontWeight.Bold,                                color = MaterialTheme.colorScheme.onSurface                            )                            Spacer(modifier = Modifier.height(12.dp))                            Text(                                text = "To colorize and restore photos, the app needs to download AI models (approx. 345MB).",                                fontSize = 14.sp,                                textAlign = TextAlign.Center,                                color = MaterialTheme.colorScheme.onSurfaceVariant                            )                            Spacer(modifier = Modifier.height(8.dp))                            Text(                                text = "A Wi-Fi connection is recommended.",                                fontSize = 13.sp,                                fontWeight = FontWeight.Medium,                                color = MaterialTheme.colorScheme.primary                            )                            Spacer(modifier = Modifier.height(32.dp))                            androidx.compose.material3.Button(                                onClick = { startDownload() },                                modifier = Modifier                                    .fillMaxWidth(0.8f)                                    .height(56.dp),                                shape = RoundedCornerShape(16.dp)                            ) {                                Text("Download AI Models", fontSize = 16.sp, fontWeight = FontWeight.Bold)                            }                        }                    }                    is HomeState.Ready -> {}                    is HomeState.Downloading -> {                        Column(                            horizontalAlignment = Alignment.CenterHorizontally,                            verticalArrangement = Arrangement.Center,                            modifier = Modifier.padding(32.dp)                        ) {                            Image(                                painter = painterResource(id = R.mipmap.ic_launcher_foreground),                                contentDescription = "App Logo",                                modifier = Modifier                                    .size(150.dp)                                    .clip(RoundedCornerShape(32.dp))                            )                            Spacer(modifier = Modifier.height(24.dp))                            Text(                                text = "Downloading AI models\u2026 ${(currentState.progress * 100).toInt()}%",                                fontSize = 16.sp,                                color = MaterialTheme.colorScheme.onSurfaceVariant                            )                            Spacer(modifier = Modifier.height(12.dp))                            LinearProgressIndicator(                                progress = { currentState.progress },                                modifier = Modifier                                    .fillMaxWidth(0.6f)                                    .height(6.dp)                            )                        }                    }                    is HomeState.Error -> {                        Column(                            horizontalAlignment = Alignment.CenterHorizontally,                            verticalArrangement = Arrangement.Center,                            modifier = Modifier.padding(32.dp)                        ) {                            Text(                                currentState.message,                                color = MaterialTheme.colorScheme.error,                                textAlign = TextAlign.Center                            )                            Spacer(modifier = Modifier.height(16.dp))                            androidx.compose.material3.Button(                                onClick = {                                    state = HomeState.Downloading(0f)                                    scope.launch {                                        downloadAllModels(repo) { p ->                                            state = HomeState.Downloading(p)                                        }.onSuccess { showHome = true }                                            .onFailure { e ->                                                state = HomeState.Error(e.message ?: "Download failed")                                            }                                    }                                }                            ) {                                Text("Retry")                            }                        }                    }                }            }        }    }}@Composableprivate fun HomeContent(    onPickPhoto: () -> Unit,    onNavigateToSettings: () -> Unit) {    Box(modifier = Modifier.fillMaxSize()) {        Column(            modifier = Modifier.fillMaxSize(),            horizontalAlignment = Alignment.CenterHorizontally        ) {            Spacer(modifier = Modifier.height(48.dp))            Image(                painter = painterResource(id = R.mipmap.ic_launcher_foreground),                contentDescription = "Makokolor Logo",                modifier = Modifier                    .size(64.dp)                    .clip(RoundedCornerShape(16.dp))            )            Spacer(modifier = Modifier.height(8.dp))            Text(                text = "Makokolorize Lite",                fontSize = 24.sp,                fontWeight = FontWeight.Bold            )            Spacer(modifier = Modifier.weight(1f))            Box(                modifier = Modifier                    .padding(horizontal = 32.dp)                    .fillMaxWidth()                    .height(280.dp)                    .clip(RoundedCornerShape(16.dp))                    .then(                        Modifier.clickable(onClick = onPickPhoto)                    ),                contentAlignment = Alignment.Center            ) {                Card(                    modifier = Modifier.fillMaxSize(),                    shape = RoundedCornerShape(16.dp),                    border = BorderStroke(2.dp, MaterialTheme.colorScheme.outlineVariant),                    colors = CardDefaults.cardColors(                        containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.3f)                    )                ) {                    Box(                        modifier = Modifier.fillMaxSize(),                        contentAlignment = Alignment.Center                    ) {                        Column(                            horizontalAlignment = Alignment.CenterHorizontally,                            verticalArrangement = Arrangement.Center                        ) {                            Icon(                                imageVector = Icons.Outlined.CameraAlt,                                contentDescription = null,                                modifier = Modifier.size(48.dp),                                tint = MaterialTheme.colorScheme.onSurfaceVariant                            )                            Spacer(modifier = Modifier.height(12.dp))                            Text(                                text = "Tap to select a photo",                                fontSize = 18.sp,                                color = MaterialTheme.colorScheme.onSurfaceVariant,                                fontWeight = FontWeight.Medium                            )                            Spacer(modifier = Modifier.height(4.dp))                            Text(                                text = "JPEG, PNG",                                fontSize = 13.sp,                                color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.6f)                            )                        }                    }                }            }            Spacer(modifier = Modifier.weight(1f))            Spacer(modifier = Modifier.height(32.dp))        }        IconButton(            onClick = onNavigateToSettings,            modifier = Modifier                .align(Alignment.TopEnd)                .padding(top = 48.dp, end = 16.dp)        ) {            Icon(                imageVector = Icons.Default.Settings,                contentDescription = "Settings",                tint = MaterialTheme.colorScheme.onSurfaceVariant            )        }    }}private suspend fun downloadAllModels(    repo: ModelRepository,    onProgress: (Float) -> Unit): Result<Unit> {    val totalSteps = 2    var completed = 0    if (!repo.isModelDownloaded()) {        repo.downloadModel { p ->            onProgress((completed.toFloat() + p) / totalSteps)        }.getOrElse { return Result.failure(it) }        completed++    }    if (!repo.isScunetModelDownloaded()) {        repo.downloadScunetModel { p ->            onProgress((completed.toFloat() + p) / totalSteps)        }.getOrElse { return Result.failure(it) }    }    return Result.success(Unit)}